from textual.app import ComposeResult, on
from textual.message import Message
from textual.widgets import Button, Label, Static
from textual.app import App


class ChildWidget(Static):
    """A widget that sends a custom message to its parent."""

    class ButtonPressed(Message):
        """Custom message sent when button is pressed."""

        def __init__(self, button_label: str) -> None:
            super().__init__()
            self.button_label = button_label

    def compose(self) -> ComposeResult:
        yield Button("Click me!", id="my_button")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Handle button press and send custom message to parent."""
        self.post_message(self.ButtonPressed("my_button"))


class ParentApp(App):
    """Main app that contains the child widget."""

    def compose(self) -> ComposeResult:
        yield Label("Parent App", id="status_label")
        yield ChildWidget(id="child")

    @on(ChildWidget.ButtonPressed)
    def handle_button_pressed(self, message: ChildWidget.ButtonPressed) -> None:
        """Handle the custom message from child widget."""
        label = self.query_one("#status_label", Label)
        label.update(f"Button pressed: {message.button_label}")


if __name__ == "__main__":
    app = ParentApp()
    app.run()

